const char* ssid     = "TP-Link S4";
const char* password = "tzp33cs8pu";

// =====================================================
// WS2811 LED STRIP
// 150 physical LEDs = 50 addressable groups
// =====================================================

#define LED_PIN    27
#define LED_COUNT  50
#define BRIGHTNESS 150

Adafruit_NeoPixel strip(
  LED_COUNT,
  LED_PIN,
  NEO_GRB + NEO_KHZ800
);

// =====================================================
// WEB SERVER
// =====================================================

WebServer server(80);

// =====================================================
// OTA UPDATE PAGE
// =====================================================

