// =====================================================
// SET ALL LEDs
// =====================================================

void setAll(byte r, byte g, byte b) {

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );

  }

  strip.show();
}


// =====================================================
// COLOR CHASE
// =====================================================

void colorChase(
  byte r,
  byte g,
  byte b,
  int wait
) {

  for (int i = 0; i < LED_COUNT; i++) {

    strip.clear();

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );

    strip.show();

    delay(wait);

    // Keep web server responsive
    server.handleClient();
  }
}


// =====================================================
// RAINBOW
// =====================================================

void rainbow(int wait) {

  for (
    long firstHue = 0;
    firstHue < 65536;
    firstHue += 256
  ) {

    for (int i = 0; i < LED_COUNT; i++) {

      int pixelHue =
        firstHue +
        (i * 65536L / LED_COUNT);

      strip.setPixelColor(
        i,
        strip.gamma32(
          strip.ColorHSV(pixelHue)
        )
      );

    }

    strip.show();

    server.handleClient();

    delay(wait);
  }
}


// =====================================================
// OTA SERVER
// =====================================================

void setupOTA() {

  // -----------------------------------------------
  // UPDATE WEBPAGE
  // -----------------------------------------------

  server.on("/", HTTP_GET, []() {

    server.send(
      200,
      "text/html",
      updatePage
    );

  });


  // -----------------------------------------------
  // FIRMWARE UPDATE
  // -----------------------------------------------

  server.on(

    "/update",

    HTTP_POST,

    []() {

      bool success =
        !Update.hasError();

      server.send(
        success ? 200 : 500,
        "text/plain",
        success
          ? "UPDATE SUCCESSFUL - REBOOTING"
          : "UPDATE FAILED"
      );

      delay(1000);

      if (success) {
        ESP.restart();
      }

    },

    []() {

      HTTPUpload& upload =
        server.upload();


      if (
        upload.status ==
        UPLOAD_FILE_START
      ) {

        Serial.println();
        Serial.println(
          "OTA UPDATE STARTED"
        );

        Serial.print(
          "File: "
        );

        Serial.println(
          upload.filename
        );

        if (
          !Update.begin(
            UPDATE_SIZE_UNKNOWN
          )
        ) {

          Update.printError(
            Serial
          );

        }

      }


      else if (
        upload.status ==
        UPLOAD_FILE_WRITE
      ) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          )
          !=
          upload.currentSize
        ) {

          Update.printError(
            Serial
          );

        }

      }


      else if (
        upload.status ==
        UPLOAD_FILE_END
      ) {

        if (
          Update.end(true)
        ) {

          Serial.println(
            "OTA UPDATE SUCCESSFUL"
          );

          Serial.print(
            "Firmware size: "
          );

          Serial.println(
            upload.totalSize
          );

        }

        else {

          Serial.println(
            "OTA UPDATE FAILED"
          );

          Update.printError(
            Serial
          );

        }

      }

    }

  );


  server.begin();

  Serial.println(
    "OTA server started."
  );

}


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  delay(500);

  // -----------------------------------------------
  // LED STRIP
  // -----------------------------------------------

  strip.begin();

  strip.setBrightness(
    BRIGHTNESS
  );

  strip.clear();

  strip.show();


  // -----------------------------------------------
  // WIFI
  // -----------------------------------------------

  WiFi.mode(WIFI_STA);

  WiFi.begin(
    ssid,
    password
  );

  Serial.println();
  Serial.print(
    "Connecting to "
  );

  Serial.println(
    ssid
  );


  while (
    WiFi.status() !=
    WL_CONNECTED
  ) {

    delay(500);

    Serial.print(".");

  }


  Serial.println();
  Serial.println();

  Serial.println(
    "=========================="
  );

  Serial.println(
    "WIFI CONNECTED!"
  );

  Serial.println(
    "=========================="
  );

  Serial.print(
    "IP Address: "
  );

  Serial.println(
    WiFi.localIP()
  );


  // -----------------------------------------------
  // START OTA
  // -----------------------------------------------

  setupOTA();

}


// =====================================================
// LOOP
// =====================================================

void loop() {

  // Always listen for OTA
  server.handleClient();


  // RED
  setAll(255, 0, 0);

  delay(800);

  server.handleClient();


  // GREEN
  setAll(0, 255, 0);

  delay(800);

  server.handleClient();


  // BLUE
  setAll(0, 0, 255);

  delay(800);

  server.handleClient();


  // WARM WHITE
  setAll(255, 110, 25);

  delay(800);

  server.handleClient();


  // OFF
  strip.clear();

  strip.show();

  delay(300);


  // ORANGE CHASE
  colorChase(
    255,
    70,
    0,
    35
  );


  // RAINBOW
  rainbow(8);

}
